select user_id userId,username,`password`, nick_name name, created_at
from users
where user_id = #{userId}


select user_id userId,username,`password`, nick_name name, created_at
from users
WHERE user_id < #{userId}

SELECT * FROM users u
LEFT JOIN user_profiles up
ON u.user_id = up.user_id
where 1 = 1

    and up.gender = #{gender}


    and up.height_cm > #{heightCm}


    and up.weight_kg > #{weightKg}

SELECT * FROM users u
LEFT JOIN user_profiles up
ON u.user_id = up.user_id


        and up.gender = #{gender}


        and up.height_cm > #{heightCm}


        AND YEAR(NOW()) - YEAR(up.birth_date) = #{age}

SELECT * FROM users
WHERE user_id in (

        #{id}

)

select user_id userId, username, password, email, nick_name name
    from users
    where username = #{username}

SELECT birth_date birthday,gender,height_cm heightCm,weight_kg weightKg
FROM users,user_profiles info
WHERE users.user_id = info.user_id AND users.user_id = #{userId}
